cat > /app/output/styles.css <<'EOF'
:root {
  --blue: #3861fb;
  --navy: #0d1421;
  --muted: #808a9d;
  --border: #eff2f5;
  --soft: #f8fafc;
  --green: #16c784;
  --red: #ea3943;
  --shadow: 0 16px 50px rgba(13, 20, 33, 0.08);
}

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: var(--navy);
  background: linear-gradient(180deg, #fbfcff 0%, #f6f8fb 420px, #fff 100%);
  font-size: 14px;
}
button, select { font: inherit; }
button { cursor: pointer; }
a { color: inherit; text-decoration: none; }
.up { color: var(--green) !important; }
.down { color: var(--red) !important; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 20;
  background: rgba(255, 255, 255, 0.94);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(16px);
}
.market-strip {
  display: flex;
  gap: 22px;
  align-items: center;
  overflow-x: auto;
  padding: 8px clamp(16px, 3vw, 38px);
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
  color: var(--muted);
  font-size: 12px;
}
.market-strip div { display: flex; gap: 6px; align-items: center; }
.market-strip strong { color: var(--navy); font-variant-numeric: tabular-nums; }
.market-strip em { font-style: normal; font-weight: 600; }
.nav-bar {
  min-height: 64px;
  padding: 0 clamp(16px, 3vw, 38px);
  display: flex;
  align-items: center;
  gap: 28px;
}
.brand { display: flex; align-items: center; gap: 10px; font-size: 18px; font-weight: 800; }
.brand-mark {
  width: 34px; height: 34px; display: grid; place-items: center;
  border-radius: 10px; background: var(--blue); color: #fff;
  box-shadow: 0 10px 22px rgba(56, 97, 251, .25);
}
.nav-links { display: flex; gap: 22px; font-weight: 600; color: #3f4a5f; flex: 1; }
.nav-links a:hover { color: var(--blue); }
.nav-actions { display: flex; gap: 10px; }
.ghost, .primary, .control, .tabs button, .promo-arrow, .read-more, .quick-asks button, .pages button, #resetFilters {
  border: 1px solid var(--border); background: #fff; border-radius: 10px; padding: 9px 13px; font-weight: 700; color: var(--navy);
}
.primary { background: var(--blue); border-color: var(--blue); color: white; }
main { width: min(100%, 1500px); margin: 0 auto; padding: 18px clamp(12px, 2vw, 28px) 0; }

.promo-wrap { display: grid; grid-template-columns: auto 1fr auto; gap: 10px; align-items: stretch; margin: 8px 0 14px; }
.promo-banner {
  display: flex; align-items: center; gap: 18px; min-height: 74px;
  border: 1px solid #dfe6ff; border-radius: 18px;
  background: linear-gradient(100deg, #eef3ff, #ffffff 52%, #f7faff);
  padding: 14px 20px; box-shadow: var(--shadow);
}
.promo-kicker { color: #fff; background: var(--blue); border-radius: 999px; padding: 6px 10px; font-size: 12px; font-weight: 800; }
.promo-banner strong { font-size: 17px; }
.promo-banner p { margin: 4px 0 0; color: var(--muted); }
.promo-arrow { width: 42px; font-size: 26px; color: var(--blue); }
.ai-alerts {
  display: flex; align-items: center; gap: 16px; justify-content: space-between;
  padding: 12px 14px; border: 1px solid var(--border); border-radius: 16px; background: white;
}
.ai-prompt { font-weight: 700; white-space: nowrap; }
.ai-prompt span { color: var(--blue); margin-right: 8px; }
.quick-asks { display: flex; gap: 8px; overflow-x: auto; }
.quick-asks button { white-space: nowrap; padding: 7px 10px; color: #4b5568; font-weight: 600; }
.hero-copy { display: grid; grid-template-columns: minmax(0, 1fr) 430px; gap: 22px; align-items: end; padding: 28px 0 18px; }
.eyebrow { margin: 0 0 8px; color: var(--blue); font-weight: 800; }
h1 { margin: 0; font-size: clamp(28px, 4vw, 46px); line-height: 1.08; letter-spacing: -0.04em; }
.hero-copy p:last-child { max-width: 900px; color: #4b5568; line-height: 1.65; font-size: 15px; }
.index-card { border: 1px solid var(--border); background: white; border-radius: 18px; padding: 18px; box-shadow: var(--shadow); }
.index-card > div:first-child { display: flex; justify-content: space-between; gap: 12px; color: var(--muted); font-weight: 700; }
.index-card strong { color: var(--navy); }
.index-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 18px; }
.index-grid span { display: grid; gap: 4px; padding: 11px; border-radius: 12px; background: var(--soft); color: var(--muted); font-size: 12px; }
.index-grid b { color: var(--navy); font-size: 14px; font-variant-numeric: tabular-nums; }

.tab-section { display: grid; gap: 10px; margin: 4px 0 14px; }
.tabs { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 2px; }
.tabs button { white-space: nowrap; color: #4b5568; }
.tabs button.active { background: #edf2ff; border-color: #cdd9ff; color: var(--blue); box-shadow: inset 0 0 0 1px rgba(56, 97, 251, .12); }
.network-tabs button.active { background: #effaf5; border-color: #bdebd8; color: #0e9f68; }
.table-card { border: 1px solid var(--border); border-radius: 18px; background: #fff; box-shadow: var(--shadow); overflow: hidden; }
.table-toolbar { display: flex; justify-content: space-between; gap: 16px; align-items: center; padding: 18px 20px; border-bottom: 1px solid var(--border); }
h2 { margin: 0; letter-spacing: -0.02em; }
.table-toolbar p { margin: 4px 0 0; color: var(--muted); }
.toolbar-actions { display: flex; gap: 8px; flex-wrap: wrap; justify-content: end; }
.control.active { color: var(--blue); background: #f2f5ff; border-color: #cfd9ff; }
.filter-panel, .columns-panel {
  margin: 0 20px 14px; padding: 14px; border: 1px solid var(--border); border-radius: 14px;
  background: #fbfcff; display: flex; gap: 12px; flex-wrap: wrap; align-items: center;
}
.filter-panel[hidden], .columns-panel[hidden] { display: none; }
.filter-panel label, .columns-panel label { display: flex; gap: 8px; align-items: center; font-weight: 700; color: #4b5568; }
.filter-panel select { border: 1px solid var(--border); border-radius: 10px; padding: 8px 10px; background: #fff; }
#resetFilters { color: var(--blue); }
.table-scroll { overflow: auto; }
table { width: 100%; border-collapse: collapse; min-width: 1180px; }
th, td { border-bottom: 1px solid var(--border); padding: 13px 14px; vertical-align: middle; }
th { position: sticky; top: 114px; z-index: 5; background: #fff; color: var(--muted); font-size: 12px; text-align: left; font-weight: 800; }
tr:hover td { background: #fbfcff; }
.rank { width: 54px; text-align: center; color: var(--muted); }
.num { text-align: right; font-variant-numeric: tabular-nums; font-feature-settings: "tnum"; }
.name-cell { display: flex; align-items: center; gap: 10px; min-width: 210px; }
.coin-icon { width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; color: white; font-size: 12px; font-weight: 800; flex: 0 0 auto; }
.coin-name { font-weight: 800; }
.coin-symbol { color: var(--muted); font-weight: 700; margin-left: 5px; }
.coin-tags { display: flex; gap: 5px; margin-top: 3px; }
.coin-tags span { font-size: 10px; color: var(--muted); background: var(--soft); border: 1px solid var(--border); border-radius: 999px; padding: 2px 6px; }
.price, .cap, .volume, .supply { font-weight: 700; }
.sparkline { width: 128px; height: 38px; display: block; margin-left: auto; }
.spark-head { text-align: right; }
.pagination { display: flex; justify-content: space-between; align-items: center; padding: 16px 20px; color: var(--muted); font-weight: 600; }
.pages { display: flex; gap: 6px; align-items: center; }
.pages button { min-width: 36px; padding: 8px 10px; }
.pages button.active { background: var(--blue); color: #fff; border-color: var(--blue); }
.market-summary, .info-content { margin-top: 22px; border: 1px solid var(--border); background: #fff; border-radius: 18px; padding: 22px; box-shadow: var(--shadow); }
.market-summary p, .info-content p { color: #4b5568; line-height: 1.75; }
.read-more { color: var(--blue); }
.info-content { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.info-content article:not(:last-child) { border-right: 1px solid var(--border); padding-right: 18px; }
.footer { margin-top: 30px; padding: 30px clamp(16px, 3vw, 38px); background: #0d1421; color: #fff; display: flex; justify-content: space-between; gap: 20px; }
.footer p { color: #aeb7c7; max-width: 520px; }
.footer-links { display: flex; gap: 14px; flex-wrap: wrap; align-content: start; justify-content: flex-end; color: #d9deea; }
.footer-links span { color: #fff; font-weight: 800; width: 100%; text-align: right; }

.hide-col { display: none; }

@media (max-width: 980px) {
  .nav-bar { flex-wrap: wrap; padding-top: 12px; padding-bottom: 12px; }
  .nav-links { order: 3; width: 100%; overflow-x: auto; }
  .hero-copy { grid-template-columns: 1fr; }
  .ai-alerts, .table-toolbar, .pagination, .footer { flex-direction: column; align-items: stretch; }
  .info-content { grid-template-columns: 1fr; }
  .info-content article:not(:last-child) { border-right: 0; border-bottom: 1px solid var(--border); padding: 0 0 14px; }
  th { top: 0; }
}
@media (max-width: 620px) {
  .market-strip { gap: 14px; }
  .promo-wrap { grid-template-columns: 1fr; }
  .promo-arrow { display: none; }
  .promo-banner { align-items: flex-start; flex-direction: column; }
  .index-grid { grid-template-columns: repeat(2, 1fr); }
}
EOF

